import React from 'react';

function BookCard({ book, user, onRequest }) {
  return (
    <div className="bg-white rounded-xl shadow-md p-6 hover:shadow-lg hover:shadow-blue-200/30 transition-all duration-200 border border-gray-100">
      <div className="text-xl font-bold text-gray-800 mb-2">{book.title}</div>
      <div className="text-purple-600 text-base mb-3">by {book.author}</div>
      {user?.role === 'student' && book.available && (
        <button 
          className="px-4 py-2 bg-gradient-button text-white border-none rounded-lg font-semibold cursor-pointer mt-2 hover:bg-gradient-button-hover transition-all duration-200"
          onClick={() => onRequest(book._id)}
        >
          Request
        </button>
      )}
      {!book.available && (
        <span className="text-red-600 font-semibold">Not Available</span>
      )}
    </div>
  );
}

export default BookCard;
